package com.example.myapplication;

import android.app.Application;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.Gravity;
import android.widget.*;
import androidx.activity.result.*;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.appcompat.app.AppCompatActivity;
import androidx.lifecycle.*;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.*;

/** OCR text goes straight to the same local models as Photo Translation, without OCR a second time. */
public class TextTranslationActivity extends BackHandlingActivity {
    static void open(AppCompatActivity a,String text,String origin){try{File dir=new File(a.getCacheDir(),"translation-exports");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException(UiText.get(R.string.ui_storage_unavailable));File file=new File(dir,"ocr-source-"+UUID.randomUUID()+".txt");Files.write(file.toPath(),text.getBytes(StandardCharsets.UTF_8));a.startActivity(new Intent(a,TextTranslationActivity.class).putExtra("text_path",file.getAbsolutePath()).putExtra("origin_path",origin));}catch(Exception e){Toast.makeText(a,UiText.format(R.string.ui_cannot_open_translation_value, e.getMessage()),Toast.LENGTH_LONG).show();}}
    public static class Task extends AndroidViewModel {
        final ExecutorService worker=Executors.newSingleThreadExecutor();final MutableLiveData<Integer> changed=new MutableLiveData<>(0);final Handler main=new Handler(Looper.getMainLooper());
        String source="",translated="",from="auto",detected="",to="en",message="",origin;boolean initialized;volatile boolean busy,cancelled,disposed;
        public Task(Application a){super(a);to=a.getSharedPreferences("photo-translation",0).getString("target","en");}
        void publish(){if(!disposed)changed.setValue(changed.getValue()+1);}void status(String value){main.post(()->{if(!disposed){message=value;publish();}});}
        void check()throws InterruptedIOException{if(cancelled||disposed||Thread.currentThread().isInterrupted())throw new InterruptedIOException(UiText.get(R.string.ui_translation_cancelled));}
        void load(String path,String restored){if(initialized)return;initialized=true;busy=true;worker.execute(()->{try{if(restored!=null){JSONObject value=new JSONObject(new String(Files.readAllBytes(new File(restored).toPath()),StandardCharsets.UTF_8));source=value.optString("source");translated=value.optString("translated");from=value.optString("from","auto");to=value.optString("to","en");main.post(()->{busy=false;message=UiText.get(R.string.ui_restored);publish();});}else{source=new String(Files.readAllBytes(new File(path).toPath()),StandardCharsets.UTF_8);main.post(()->{busy=false;if(!getApplication().getSharedPreferences("photo-translation",0).contains("target"))try{to=PhotoLanguageDetector.detect(getApplication(),source).equals("el")?"en":"el";}catch(Exception ignored){}publish();translate();});}}catch(Exception e){main.post(()->{busy=false;message=UiText.format(R.string.ui_cannot_open_ocr_text_value, e.getMessage());publish();});}});}
        void translate(){if(busy)return;if(source.trim().isEmpty()||source.length()>1000000){message=UiText.get(R.string.ui_select_readable_text_from_fewer_pages_up_to_1_000_000_characters);publish();return;}String input=source,sourceChoice=from,targetChoice=to;busy=true;cancelled=false;translated="";message=UiText.get(R.string.ui_preparing_local_translation);publish();worker.execute(()->{try{String detected=sourceChoice.equals("auto")?PhotoLanguageDetector.detect(getApplication(),input):sourceChoice;TranslationCatalog.language(getApplication(),detected);List<String> route=TranslationCatalog.route(detected,targetChoice);ArrayList<String> parts=new ArrayList<>();int offset=0;while(offset<input.length()){int end=Math.min(input.length(),offset+1200);if(end<input.length()){int split=input.lastIndexOf('\n',end);if(split<=offset+400)split=input.lastIndexOf(' ',end);if(split>offset+400)end=split+1;}parts.add(input.substring(offset,end));offset=end;}
            for(String direction:route){check();JSONObject model=null;JSONArray catalog=LanguageModels.catalog(getApplication(),"translation");for(int i=0;i<catalog.length();i++)if(direction.equals(catalog.getJSONObject(i).getString("code")))model=catalog.getJSONObject(i);if(model==null)throw new IOException(UiText.get(R.string.ui_this_language_pair_is_unavailable));if(!LanguageModels.installed(getApplication(),"translation",model)){status(UiText.format(R.string.ui_first_time_language_download_value_document_text_stays_on_this_device, direction));LanguageModels.download(getApplication(),"translation",model,()->cancelled||disposed,(done,total)->status(UiText.format(R.string.ui_downloading_value_value, direction, done*100/Math.max(1,total))));}}
            for(String direction:route)try(OfflineTranslator translator=new OfflineTranslator(getApplication(),direction)){for(int i=0;i<parts.size();i++){check();String original=parts.get(i);if(!original.trim().isEmpty())parts.set(i,translator.translate(original));status(UiText.format(R.string.ui_translating_value_value_value, direction, (i+1), parts.size()));}}
            check();String output=String.join("\n\n",parts);main.post(()->{if(disposed)return;busy=false;if(cancelled){message=UiText.get(R.string.ui_translation_cancelled);}else{this.detected=detected;translated=output;message=UiText.format(R.string.ui_ready_value_value, LocalTranslationActivity.languageName(detected), LocalTranslationActivity.languageName(targetChoice));}publish();});
        }catch(Exception|LinkageError|OutOfMemoryError e){main.post(()->{if(disposed)return;busy=false;message=cancelled ? UiText.get(R.string.ui_translation_cancelled) : UiText.format(R.string.ui_could_not_translate_value, e.getMessage());publish();});}});}
        @Override protected void onCleared(){disposed=true;cancelled=true;worker.shutdownNow();}
    }
    private Task task;private EditText input;private TextView output,status;private Button source,target,translate,copy,share,saveButton;private ActivityResultLauncher<String> save;
    @Override public void onCreate(Bundle state){super.onCreate(state);task=new ViewModelProvider(this).get(Task.class);task.origin=getIntent().getStringExtra("origin_path");save=registerForActivityResult(new ActivityResultContracts.CreateDocument("text/plain"),uri->{if(uri!=null)save(uri);});build();task.changed.observe(this,value->refresh());String restored=state==null?null:state.getString("session_file");if(task.origin!=null&&!FolderLock.ensureDocument(this,task.origin,()->task.load(getIntent().getStringExtra("text_path"),restored)))return;task.load(getIntent().getStringExtra("text_path"),restored);}
    private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(android.widget.LinearLayout.VERTICAL);root.setBackgroundColor(AppTheme.background());Button back=new Button(this);back.setText(UiText.get(R.string.ui_back_text_translation));root.addView(back);back.setOnClickListener(v->handleBackPressed());LinearLayout languages=new LinearLayout(this);source=new Button(this);target=new Button(this);languages.addView(source,new LinearLayout.LayoutParams(0,-2,1));languages.addView(target,new LinearLayout.LayoutParams(0,-2,1));root.addView(languages);source.setOnClickListener(v->choose(true));target.setOnClickListener(v->choose(false));ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(android.widget.LinearLayout.VERTICAL);body.setPadding(18,8,18,16);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));input=new EditText(this);input.setTextColor(AppTheme.ink());input.setHintTextColor(AppTheme.muted());input.setHint(UiText.get(R.string.ui_recognized_text_edit_before_translating));input.setGravity(Gravity.TOP);input.setMinLines(3);body.addView(input);output=new TextView(this);output.setTextColor(AppTheme.ink());output.setTextSize(17);output.setTextIsSelectable(true);output.setPadding(0,20,0,20);body.addView(output);status=new TextView(this);status.setTextColor(AppTheme.muted());root.addView(status);LinearLayout actions=new LinearLayout(this);copy=new Button(this);copy.setText(UiText.get(R.string.ui_copy));share=new Button(this);share.setText(UiText.get(R.string.ui_share));saveButton=new Button(this);saveButton.setText(UiText.get(R.string.ui_save_txt));for(Button b:new Button[]{copy,share,saveButton})actions.addView(b,new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);copy.setOnClickListener(v->{if(authorized())((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Translation",task.translated));});share.setOnClickListener(v->{if(!authorized())return;try{File file=export();Uri uri=FileProvider.getUriForFile(this,getPackageName()+".files",file);startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),UiText.get(R.string.ui_share_translation)));}catch(Exception e){toast(e.getMessage());}});saveButton.setOnClickListener(v->{if(authorized())save.launch("Translated-text.txt");});translate=new Button(this);translate.setText(UiText.get(R.string.ui_translate));root.addView(translate);translate.setOnClickListener(v->{if(!authorized())return;if(task.busy){task.cancelled=true;task.message=UiText.get(R.string.ui_cancelling_after_the_current_step);task.publish();}else{task.source=input.getText().toString();task.translate();}});UiInsets.applyKeyboardAware(root);setContentView(root);}
    private boolean authorized(){return task.origin==null||FolderLock.ensureDocument(this,task.origin,this::refresh);}
    private void refresh(){if(isFinishing())return;if((!input.hasFocus()||input.length()==0)&&!input.getText().toString().equals(task.source))input.setText(task.source);input.setEnabled(!task.busy);source.setText(task.from.equals("auto") ? UiText.get(R.string.ui_auto_detect_85cd1ac0) : LocalTranslationActivity.languageName(task.from));target.setText(UiText.format(R.string.ui_to_value_bce8190c, LocalTranslationActivity.languageName(task.to)));source.setEnabled(!task.busy);target.setEnabled(!task.busy);output.setText(task.translated);status.setText(task.message);translate.setText(task.busy ? UiText.get(R.string.ui_cancel) : UiText.get(R.string.ui_translate));for(Button b:new Button[]{copy,share,saveButton})b.setEnabled(!task.busy&&!task.translated.isEmpty());if(task.origin!=null)FolderLock.guard(this,task.origin);}
    private void choose(boolean from){try{List<TranslationCatalog.Language> languages=TranslationCatalog.languages(this);String[] labels=new String[languages.size()+(from?1:0)];if(from)labels[0]=UiText.get(R.string.ui_auto_detect_85cd1ac0);for(int i=0;i<languages.size();i++)labels[i+(from?1:0)]=languages.get(i).label();new ProtectedDialogs.Builder(this).setTitle(from ? UiText.get(R.string.ui_source_language) : UiText.get(R.string.ui_translate_to)).setItems(labels,(d,w)->{task.source=input.getText().toString();if(from)task.from=w==0?"auto":languages.get(w-1).code;else{task.to=languages.get(w).code;getSharedPreferences("photo-translation",0).edit().putString("target",task.to).apply();}task.translate();}).show();}catch(Exception e){toast(e.getMessage());}}
    private File export()throws Exception{File dir=new File(getCacheDir(),"translation-exports");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException(UiText.get(R.string.ui_storage_unavailable));File file=new File(dir,"translated-"+UUID.randomUUID()+".txt");Files.write(file.toPath(),task.translated.getBytes(StandardCharsets.UTF_8));return file;}
    private void save(Uri uri){if(task.origin!=null&&!FolderLock.ensureDocument(this,task.origin,()->save(uri)))return;task.worker.execute(()->{String value=task.translated;if(value.isEmpty()){runOnUiThread(()->toast(UiText.get(R.string.ui_could_not_save_text)));return;}try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException(UiText.get(R.string.ui_destination_unavailable));out.write(value.getBytes(StandardCharsets.UTF_8));runOnUiThread(()->toast(UiText.get(R.string.ui_translation_saved)));}catch(Exception e){runOnUiThread(()->toast(UiText.format(R.string.ui_could_not_save_value, e.getMessage())));}});}
    @Override protected void onResume(){super.onResume();if(task.origin!=null)FolderLock.guard(this,task.origin);}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(!task.busy)task.source=input.getText().toString();try{File dir=new File(getCacheDir(),"translation-exports");dir.mkdirs();File file=new File(dir,"text-session-"+UUID.randomUUID()+".json");Files.write(file.toPath(),new JSONObject().put("source",task.source).put("translated",task.translated).put("from",task.from).put("to",task.to).toString().getBytes(StandardCharsets.UTF_8));state.putString("session_file",file.getAbsolutePath());}catch(Exception ignored){}}
    @Override public void handleBackPressed(){if(task.busy)task.cancelled=true;super.handleBackPressed();}
    private void toast(String value){Toast.makeText(this,value,Toast.LENGTH_LONG).show();}
}
